import {riskDimension,PERSPECTIVES,DEFAULT_COLUMNS,defaultView,filterRecords,sortedRecords,words,exportView,currentViewCSV} from '../../integrations/javascript/evidence-model.mjs';
import {getView,setView,savedViews,saveNamed,applyNamed} from './report-state.js';
import {esc,list,evidenceReader,recordDetails,openReader,translationNotes,extractionNotes,sourceCoverage,publicationControl,originalPage,preparationNotes} from './evidence-reader.js';
import {toolbar,visualSummary,recordTable,deliveryMatrix,dateTable,selected} from './report-components.js';
import {taskSummary} from './report-results.js';
export {filterRecords};
const SECTION_NAMES={scope_and_method:'Scope and method',risk_context_and_drr:'Risks and disaster risk reduction',adaptation_and_resilience:'Adaptation and resilience',mitigation:'Climate mitigation',implementation_and_actors:'Implementation and responsibilities',finance_and_support:'Finance and support',inclusion_and_development:'Inclusion and development',monitoring:'Monitoring',changes_and_coherence:'Changes and coherence',limitations:'Limitations'};
const SECTION_STATE={found:'Evidence found',not_found_in_scope:'Not found in this scope',not_applicable:'Not applicable',not_processed:'Not processed'};
const FINDING_KIND={source_fact:'Source statement',source_reported_observation:'Source-reported observation',derived:'Derived analysis',analyst_suggestion:'Analyst suggestion'};
function finding(f,index,prefix='headline'){return `<article class="finding"><span class="record-meta">${esc(FINDING_KIND[f.kind]||words(f.kind))}</span><p>${esc(f.text_en)}</p>${f.limitations.length?`<p class="qualification">${f.limitations.map(esc).join(' · ')}</p>`:''}${f.calculation?`<p class="qualification">Calculation: ${esc(f.calculation)}</p>`:''}<button class="table-link" data-finding="${prefix}:${index}">Inspect evidence · ${f.citations.evidence_ids.length} passages →</button></article>`;}
function scope(p,data){return `<header class="report-scope"><div><span class="eyebrow">${p.presentation_fixture?'SYNTHETIC INTERFACE FIXTURE':p.synthetic?'SYNTHETIC SAVED PROFILE':p.generation?'GENERATED COUNTRY PROFILE':'IMPORTED COUNTRY PROFILE'}</span><p><strong>${p.sources.length} source${p.sources.length===1?'':'s'}</strong> · ${p.extraction.records.length} source records · Saved ${esc(p.created_at?.slice(0,10)||'date unavailable')}</p>${p.synthetic&&!p.presentation_fixture?'<p class="scope-note">Synthetic saved example · not a country assessment.</p>':''}</div><details class="export-menu"><summary>Export</summary><button data-copy-link>Copy local view link</button><button data-export="html">Export current view · readable HTML</button><button data-export="csv">Export current view · CSV</button><button data-export="json">Export current view · evidence JSON</button><button data-export="full">Export full saved report · JSON</button>${!p.presentation_fixture?`<a href="/api/profiles/${encodeURIComponent(p.country_code)}?format=csv&amp;version=${encodeURIComponent(p.id)}${p.synthetic?'&amp;synthetic=1':''}" download>Export full register · CSV</a>`:''}<p>Current view keeps filters. Full report includes all saved records and narrative.</p></details></header>${data.selection?.stale_sources?'<p class="callout">Newer source inputs are pending. This saved version still uses its previous sources.</p>':''}${p.report.availability==='partial'?'<p class="callout">Partial coverage · Findings cover the processed material only.</p>':''}`;}
function scopeDetails(p){return `<details class="scope-details"><summary>Documents, coverage and limitations</summary><ul>${p.sources.map(d=>`<li>${esc(d.title)} · ${d.pages} pages</li>`).join('')}</ul>${list(p.report.limitations)}${extractionNotes(p)}<p>Source-record counts are not unique commitments. Repeated statements remain attached to their documents. Source-reported observations are not independently verified.</p></details>`;}
function overview(p,v,records){return `<div class="overview-layout"><section><div class="section-title"><h2>What the sources say</h2><span class="record-meta">Saved narrative · full report scope</span></div>${Object.values(v.filters).some(x=>Array.isArray(x)?x.length:!!x)?'<p class="muted">Filters affect the records below. These saved findings cover the full report scope and have not been regenerated for these filters.</p>':''}${p.report.headline_findings.map((f,i)=>finding(f,i)).join('')||'<p>No headline findings were saved.</p>'}${v.sections.priorities&&p.report.prioritized_commitments.length?`<section class="narrative-section"><h2>Priorities and their basis</h2><p class="muted">Saved analytical selection. Source-stated priorities are identified separately by record labels.</p>${p.report.prioritized_commitments.map((r,i)=>`<article><h3>${esc(p.extraction.records.find(x=>x.local_id===r.commitment_id)?.label_en||r.commitment_id)}</h3><p>${esc(r.reason)}</p><button class="table-link" data-priority="${i}">Inspect priority evidence →</button></article>`).join('')}</section>`:''}</section><aside class="overview-aside"><details><summary>Scope, qualifications and follow-up questions</summary>${list(p.report.limitations)}<p class="muted">${p.report.sections.filter(s=>s.state==='not_processed').length} sections not processed. ${p.report.sections.filter(s=>s.state==='not_found_in_scope').length} sections have no findings in scope.</p>${v.sections.questions&&p.report.followup_questions.length?`<h3>Questions to investigate</h3>${p.report.followup_questions.map((f,i)=>finding(f,i,'question')).join('')}`:''}</details></aside></div><section class="narrative-section"><h2>Explore the evidence</h2><p>${records.length} records match your selected perspective and filters.</p><button data-explore class="primary">Open these records in Policy register →</button></section>`;}
function narrative(p){return `<section class="narrative-section"><h2>Full thematic narrative</h2>${p.report.sections.map((s,i)=>`<details class="thematic-section"><summary>${esc(SECTION_NAMES[s.section_id]||words(s.section_id))}<span>${esc(SECTION_STATE[s.state]||s.state)}</span></summary>${s.findings.map((f,j)=>finding(f,j,`section-${i}`)).join('')}${s.gap_note?`<p>${esc(s.gap_note)}</p>`:''}</details>`).join('')}</section>`;}
function provenance(p){return `<details class="scope-details"><summary>Version, definitions and run details</summary><p>${esc(p.provenance_note)}</p><p>Version ${esc(p.id)} · ${esc(p.created_at)}</p><p>${p.generation?'GENERATED COUNTRY PROFILE · Automated checks passed; no expert review is established by these checks.':'IMPORTED COUNTRY PROFILE · Local checks passed; generation provenance is unverified.'}</p><p>Archived codebook: taxonomy ${esc(p.validation_codebook?.taxonomy_version||'unavailable')} · vocabulary ${esc(p.validation_codebook?.vocabulary_version||'unavailable')} · guide ${esc(p.validation_codebook?.guide_version||'unavailable')}.</p><p>${p.generation?'Generation requests and model receipts are archived.':'Generation method is not verified.'} No implementation progress is inferred.</p><details><summary>Technical archive and validation receipt</summary><pre class="code-sample">${esc(JSON.stringify({validation:p.validation,archive:p.archive,generation:p.generation},null,2))}</pre></details></details>`;}
function documents(p){return `<section><h2>Documents & translations</h2><p>Read saved pages in the original language and English. Page numbers refer to the physical document.</p>${p.sources.map((d,i)=>`<section class="narrative-section"><h3>${esc(d.title)}</h3><p class="muted">${new Set(d.segments.map(s=>s.page)).size} pages with saved text of ${d.pages} document pages · ${[...new Set(d.segments.map(s=>s.language))].map(esc).join(', ')||'Language unavailable'}</p>${!d.segments.length?'<p>No reading copy is available for this document.</p>':''}${d.path?.toLowerCase().endsWith('.pdf')?`<a href="/api/ai/documents/${encodeURIComponent(p.id)}/${encodeURIComponent(d.document_id)}" download>Download archived original PDF</a>`:''}<label>Read a page<select data-read-document="${i}"><option value="">Choose a stored page</option>${[...new Set(d.segments.map(s=>s.page))].map(page=>`<option value="${page}">Page ${page}</option>`).join('')}</select></label></section>`).join('')}</section>`;}
export function storedProfile(data,view='brief',override){
 const p=data?.profile;
 if(view==='history')return `<section class="paper"><h2>Version history</h2><p>${data.selection?.pinned?'Pinned version':'Latest checked local version'}. Read a saved version or pin it for the country. Unpin restores the latest eligible version.</p>${data.selection?.pinned?'<button data-history-unpin>Unpin country version</button>':''}${data.history.map(r=>`<article><h3>${esc(new Date(r.created_at).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'medium'}))}</h3><p>${r.state==='checked'?(r.published?'Published':'Unpublished'):esc(r.state)}${r.id===data.selection?.profile_id?' · Selected country version':''}</p><details><summary>Version details</summary><p>${esc(r.id)} · ${esc(r.created_at)}</p></details>${r.state==='checked'?`<button data-history-read="${esc(r.id)}">Read this version</button> ${r.published?`<button data-history-pin="${esc(r.id)}">Pin this version</button>`:''} <button data-publication="${esc(r.id)}" data-published="${r.published?'false':'true'}">${r.published?'Unpublish':'Publish this version'}</button>`:''}${r.error?`<p class="callout">${esc(r.error)}</p>`:''}</article>`).join('')||'<p>No earlier versions in this scope.</p>'}</section>`;
 if(!p)return '<section class="empty-state"><h2>No saved profile</h2><p>Inspect the sources and generation state to prepare this country.</p></section>';
 const v=override||getView(p),records=sortedRecords(p,filterRecords(p,v.filters,v.perspective),v.sort);
 const task=taskSummary(p,records,v);
 const links=p.reconciliation?`<details class="scope-details"><summary>Proposed source links and unresolved differences</summary><p>No records are automatically merged. Relationships remain proposed analysis.</p>${(p.reconciliation.relations||[]).map((r,i)=>`<article><strong>${esc(words(r.kind))} · proposed</strong><p>${esc(r.reason)}</p><button class="table-link" data-relation="${i}">Inspect both sources →</button></article>`).join('')}${list(p.reconciliation.issues||[])}</details>`:'';
 return `<div data-profile-host data-view="${view}" class="report-workspace">${scope(p,data)}${publicationControl(p)}${sourceCoverage(p)}<p class="view-notice" role="status" data-view-notice></p>${view==='documents'?documents(p):`${task}${view==='brief'?overview(p,v,records):''}${view==='brief'?'<details class="overview-explore"><summary>Explore records by theme, target or responsibility</summary>':''}${toolbar(p,v)}<p role="status" data-profile-count>${records.length} of ${p.extraction.records.length} source records shown · ${PERSPECTIVES[v.perspective]}</p>${view==='brief'?'':`<div class="section-title"><h2>Policy register</h2><span class="record-meta">${records.length} source records · not a count of unique commitments</span></div>${links}`}${!records.length?`<section class="empty-state"><h3>${p.extraction.records.length?'No source records match':'No extracted records available'}</h3><p>Change a filter or reset the view. This does not establish national policy absence.</p><button data-clear-all>Clear filters</button></section>`:`${v.sections.visuals?`${view==='commitments'?'<details class="record-summary"><summary>Visual summary of these records</summary>':''}<div class="visual-grid">${v.perspective==='delivery'?deliveryMatrix(p,records,v.filters):v.perspective==='targets'?dateTable(records,v.filters):visualSummary(p,records,v.perspective==='risk'?'hazards':'domain')}${v.perspective==='risk'?visualSummary(p,records,riskDimension(p)):''}</div>${view==='commitments'?'</details>':''}`:''}${view==='brief'?'':recordTable(p,records,v)}`}${view==='brief'?'</details>'+narrative(p):''}`}${scopeDetails(p)}${provenance(p)}</div>`;
}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function readableExport(p,v,view='commitments'){
 const bundle=exportView(p,v),rows=bundle.records;
 return `<!doctype html><html lang="en"><meta charset="utf-8"><title>Policy evidence · ${esc(p.id)}</title><style>body{font:16px/1.6 system-ui;max-width:1050px;margin:40px auto;padding:20px;color:#17323a}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccd8dc;padding:12px;text-align:left}section,article{margin:22px 0}summary{cursor:pointer}dt{font-weight:bold}dd{margin-bottom:10px}pre{white-space:pre-wrap}h1,h2,h3{line-height:1.3}.bilingual{display:grid;grid-template-columns:1fr 1fr;gap:24px}@media(max-width:650px){.bilingual{display:block}}</style><h1>Current filtered view · ${PERSPECTIVES[v.perspective]}</h1><p>${p.synthetic?'Synthetic evidence · ':''}Version ${esc(p.id)} · ${bundle.exported_at} · ${rows.length} source records</p><p>Filters: ${esc(JSON.stringify(v.filters))}. Codebook: ${esc(JSON.stringify(v.codebook))}.</p>${list(bundle.limitations)}${sourceCoverage(p)}${extractionNotes(p)}${view==='brief'?`<h2>Saved findings · full report scope</h2><p>These findings were not regenerated for the filters.</p>${p.report.headline_findings.map(f=>`<article><p>${esc(f.text_en)}</p>${list(f.limitations)}${evidenceReader(p,f.citations.evidence_ids,{originalLinks:false})}</article>`).join('')}`:''}<p>Open original PDFs from this saved version in the local tracker.</p><h2>Filtered records and evidence annex</h2>${rows.map(r=>`<section><h2>${esc(r.label_en)}</h2>${recordDetails(p,r,{originalLinks:false})}</section>`).join('')}<h2>Definitions used</h2>${(p.validation_codebook?.topics||[]).filter(t=>rows.some(r=>r.labels.topic_ids.includes(t.id))).map(t=>`<p><strong>${esc(t.name)}</strong>: ${esc(t.definition)}</p>`).join('')}</html>`;
}
export function bindStoredProfile(container,data,{onExplore,onCopyLink}={}){
 const p=data?.profile,host=container.querySelector('[data-profile-host]');if(!p||!host)return;
 let v=structuredClone(getView(p));let pendingFilters=structuredClone(v.filters);const view=host.dataset.view;
 const redraw=(focusId,notice='')=>{const scroll=window.scrollY,expanded=[...host.querySelectorAll('details')].filter(d=>d.open).map(d=>d.querySelector(':scope > summary')?.textContent);setView(p,v);host.outerHTML=storedProfile(data,view);bindStoredProfile(container,data,{onExplore,onCopyLink});const fresh=container.querySelector('[data-profile-host]');fresh.querySelectorAll('details').forEach(d=>{d.open=expanded.includes(d.querySelector(':scope > summary')?.textContent);});fresh.querySelector('[data-view-notice]').textContent=notice;const focus=focusId&&document.getElementById(focusId);focus?.focus({preventScroll:true});if(focus?.type==='search')focus.setSelectionRange(focus.value.length,focus.value.length);window.scrollTo(0,scroll);};
 host.querySelectorAll('[data-perspective]').forEach(b=>b.onclick=()=>{v={...v,perspective:b.dataset.perspective,columns:[...DEFAULT_COLUMNS[b.dataset.perspective]]};redraw(b.id);});
 host.querySelectorAll('[data-filter]').forEach(c=>c.addEventListener(c.type==='search'?'input':'change',()=>{if(c.value==='__multiple')return;v.filters[c.dataset.filter]=c.dataset.filter==='query'?c.value:c.value?[c.value]:[];redraw(c.id);}));
 host.querySelectorAll('[data-clear-all]').forEach(b=>b.onclick=()=>{v.filters={};redraw('pf-query','Filters cleared.');});
 host.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>{delete v.filters[b.dataset.clear];redraw('pf-query');});
 host.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>{v=defaultView(p);redraw('pf-query','Default view restored.');});
 host.querySelectorAll('[data-setting]').forEach(c=>c.onchange=()=>{v[c.dataset.setting]=c.value;redraw(c.id);});
 host.querySelectorAll('[data-column]').forEach(c=>c.onchange=()=>{v.columns=c.checked?[...v.columns,c.dataset.column]:v.columns.filter(x=>x!==c.dataset.column);redraw(c.id);});
 host.querySelectorAll('[data-section]').forEach(c=>c.onchange=()=>{v.sections[c.dataset.section]=c.checked;redraw(c.id);});
 host.querySelectorAll('[data-multi]').forEach(c=>c.onchange=()=>{const k=c.dataset.multi;pendingFilters[k]=c.checked?[...selected(pendingFilters[k]),c.value]:selected(pendingFilters[k]).filter(x=>x!==c.value);host.querySelector('[data-view-notice]').textContent='Filter draft changed. Choose Apply selected filters to update the records.';});
 host.querySelector('[data-apply-filters]')?.addEventListener('click',()=>{v.filters=pendingFilters;redraw('pf-query','Filters applied.');});
 host.querySelector('[data-save-view]')?.addEventListener('click',()=>{try{const name=host.querySelector('#view-name').value;const persisted=saveNamed(p,v,name);v.name=name;redraw('view-name',persisted?'Named view saved on this browser.':'Saved for this tab only; browser storage unavailable.');}catch(e){host.querySelector('[data-view-notice]').textContent=e.message;}});
 host.querySelector('[data-load-view]')?.addEventListener('click',()=>{try{const index=host.querySelector('#saved-view').value;if(index==='')throw Error('Choose a saved view.');const item=savedViews(p)[Number(index)];v=applyNamed(p,item);redraw('pf-query',`Applied “${item.name}” to this version. Definitions come from the version being read.`);}catch(e){host.querySelector('[data-view-notice]').textContent=e.message;}});
 const explore=()=>{setView(p,v);if(onExplore)onExplore();else{host.outerHTML=storedProfile(data,'commitments');bindStoredProfile(container,data);}};
 host.querySelector('[data-explore]')?.addEventListener('click',explore);
 host.querySelectorAll('[data-bucket]').forEach(b=>b.onclick=()=>{v.filters[b.dataset.bucket]=[b.dataset.value];explore();});
 host.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{const r=p.extraction.records.find(r=>r.local_id===b.dataset.record);if(r)openReader(r.label_en,recordDetails(p,r));});
 host.querySelectorAll('[data-finding]').forEach(b=>b.onclick=()=>{const [prefix,index]=b.dataset.finding.split(':');const items=prefix==='headline'?p.report.headline_findings:prefix==='question'?p.report.followup_questions:p.report.sections[Number(prefix.split('-')[1])].findings;const f=items[Number(index)];openReader(FINDING_KIND[f.kind],`<p class="brief-lead">${esc(f.text_en)}</p>${list(f.limitations)}${f.calculation?`<p>Calculation: ${esc(f.calculation)}</p>`:''}${evidenceReader(p,f.citations.evidence_ids)}`);});
 host.querySelectorAll('[data-priority]').forEach(b=>b.onclick=()=>{const row=p.report.prioritized_commitments[Number(b.dataset.priority)];openReader('Priority and its basis',`<p>${esc(row.reason)}</p>${evidenceReader(p,row.evidence_ids)}`);});
 host.querySelectorAll('[data-relation]').forEach(b=>b.onclick=()=>{const r=p.reconciliation.relations[Number(b.dataset.relation)];openReader('Proposed relationship',`<p>${esc(r.reason)}</p>${evidenceReader(p,r.evidence_ids)}`);});
 host.querySelectorAll('[data-read-document]').forEach(c=>c.onchange=()=>{if(!c.value)return;const d=p.sources[Number(c.dataset.readDocument)];openReader(`${d.title} · page ${c.value}`,originalPage(p,d,Number(c.value))+preparationNotes(d,Number(c.value))+d.segments.filter(s=>String(s.page)===c.value).map(s=>`<section class="bilingual"><section><h3>Original · ${esc(s.language)}</h3><p lang="${esc(s.language)}" dir="auto">${esc(s.text)}</p></section><section><h3>English · ${esc(words(s.translation_method))}</h3><p lang="en">${esc(s.english_text)}</p></section></section>${translationNotes(s)}`).join(''));});
 host.querySelector('[data-copy-link]')?.addEventListener('click',()=>onCopyLink?.(v));
 host.querySelectorAll('[data-export]').forEach(b=>b.onclick=async()=>{const kind=b.dataset.export,name=`${p.country_code}-${p.id}-${kind==='full'?'full-report':'filtered-view'}`;if(kind==='csv')download(currentViewCSV(p,v),name+'.csv','text/csv;charset=utf-8');else if(kind==='html')download(readableExport(p,v,view),name+'.html','text/html;charset=utf-8');else {let output=kind==='full'?p:exportView(p,v);if(kind==='full'&&!p.presentation_fixture){try{const response=await fetch(`/api/profiles/${encodeURIComponent(p.country_code)}?version=${encodeURIComponent(p.id)}&archive=1${p.synthetic?'&synthetic=1':''}`);if(!response.ok)throw Error('Could not read the archived generation files.');output=(await response.json()).profile;}catch(e){openReader('Export unavailable',esc(e.message));return;}}download(JSON.stringify(output,null,2),name+'.json','application/json');}});
}
